import React, { useState, useMemo, useCallback } from 'react';
import { lazy, Suspense } from 'react';
import { FixedSizeList } from 'react-window';

// ============================================================
// 1. React.memo：子组件只有 name 变化时才重渲染
// ============================================================
const ExpensiveChild = React.memo(({ name, onClick }) => {
  console.log('ExpensiveChild render');
  // 假设这里有很多 DOM 和计算
  return <div onClick={onClick}>{name}</div>;
});

// 自定义比较：只比较 name，忽略 onClick 变化
const MemoByName = React.memo(ExpensiveChild, (prev, next) => {
  return prev.name === next.name;
});

// ============================================================
// 2. useCallback 稳定函数引用 + useMemo 缓存昂贵计算
// ============================================================
function Parent() {
  const [count, setCount] = useState(0);
  const [users] = useState([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);

  // useCallback：每次 Parent 渲染，handleClick 引用不变
  // → ExpensiveChild 的 onClick prop 引用不变 → memo 的浅比较通过
  const handleClick = useCallback(() => {
    console.log('clicked');
  }, []);

  // useMemo：只有 users 变化时才重新排序
  const sortedUsers = useMemo(() => {
    console.log('sorting...');
    return [...users].sort((a, b) => a.name.localeCompare(b.name));
  }, [users]);

  return (
    <div>
      <button onClick={() => setCount(c => c + 1)}>
        Count: {count}
      </button>
      {sortedUsers.map(u => (
        <ExpensiveChild key={u.id} name={u.name} onClick={handleClick} />
      ))}
    </div>
  );
}

// ============================================================
// 3. 代码分割：路由级懒加载
// ============================================================
const Home = lazy(() => import('./pages/Home'));
const About = lazy(() => import('./pages/About'));

function App() {
  return (
    <Suspense fallback={<div>Loading...</div>}>
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/about" element={<About />} />
      </Routes>
    </Suspense>
  );
}

// ============================================================
// 4. 虚拟列表（react-window FixedSizeList）
// ============================================================
function VirtualList({ items }) {
  const Row = useCallback(({ index, style }) => (
    <div style={style}>{items[index].name}</div>
  ), [items]);

  return (
    <FixedSizeList
      height={400}
      width={300}
      itemCount={items.length}
      itemSize={50}       // 每行固定 50px
      overscanCount={5}   // 可视区外多渲染 5 行缓冲
    >
      {Row}
    </FixedSizeList>
  );
}

// ============================================================
// 5. 状态下沉：把 input 的 state 隔离到独立组件
// ============================================================
// ❌ 差的做法：input 变化 → 整个 App 重渲染 → ExpensiveTree 也重渲染
function BadApp() {
  const [text, setText] = useState('');
  return (
    <>
      <input value={text} onChange={e => setText(e.target.value)} />
      <ExpensiveTree />
    </>
  );
}

// ✅ 好的做法：把 text state 下沉到 SearchInput
function SearchInput() {
  const [text, setText] = useState('');
  return <input value={text} onChange={e => setText(e.target.value)} />;
}

function GoodApp() {
  return (
    <>
      <SearchInput />
      <ExpensiveTree />
    </>
  );
}
